mapper.sql:
SELECT

id,

create_time, update_time,

organ_id, revision_id, task_type, task_status, idempotency_key, attempt_no, available_time, lease_owner, lease_expire_time, provider_name, model_name, trace_id, started_time, finished_time, error_code, error_summary,

delete_flag,

version
FROM knowledge_task



        AND id = #{id, jdbcType=BIGINT}


        AND id IN

            #{item, jdbcType=BIGINT}





            AND create_time >= #{createTime[0], jdbcType=TIMESTAMP}


            AND create_time <= #{createTime[1], jdbcType=TIMESTAMP}


            AND create_time BETWEEN #{createTime[0], jdbcType=TIMESTAMP}
            AND #{createTime[1], jdbcType=TIMESTAMP}




            AND update_time >= #{updateTime[0], jdbcType=TIMESTAMP}


            AND update_time <= #{updateTime[1], jdbcType=TIMESTAMP}


            AND update_time BETWEEN #{updateTime[0], jdbcType=TIMESTAMP}
            AND #{updateTime[1], jdbcType=TIMESTAMP}




        AND organ_id = #{organId, jdbcType=BIGINT}


        AND revision_id = #{revisionId, jdbcType=BIGINT}


        AND task_type = #{taskType, jdbcType=VARCHAR}


        AND task_status = #{taskStatus, jdbcType=VARCHAR}


        AND idempotency_key = #{idempotencyKey, jdbcType=VARCHAR}


        AND attempt_no = #{attemptNo, jdbcType=INTEGER}


        AND available_time = #{availableTime, jdbcType=TIMESTAMP}


        AND lease_owner = #{leaseOwner, jdbcType=VARCHAR}


        AND lease_expire_time = #{leaseExpireTime, jdbcType=TIMESTAMP}


        AND provider_name = #{providerName, jdbcType=VARCHAR}


        AND model_name = #{modelName, jdbcType=VARCHAR}


        AND trace_id = #{traceId, jdbcType=VARCHAR}


        AND started_time = #{startedTime, jdbcType=TIMESTAMP}


        AND finished_time = #{finishedTime, jdbcType=TIMESTAMP}


        AND error_code = #{errorCode, jdbcType=VARCHAR}


        AND error_summary = #{errorSummary, jdbcType=VARCHAR}


    AND (delete_flag = 0 OR delete_flag IS NULL)

mapper.update:
UPDATE knowledge_task
SET task_status = 'CANCELED',
    finished_time = #{finishedTime, jdbcType=TIMESTAMP},
    update_time = #{updateTime, jdbcType=TIMESTAMP},
    version = version + 1
WHERE id = #{taskId, jdbcType=BIGINT}
  AND organ_id = #{organId, jdbcType=BIGINT}
  AND version = #{expectedVersion, jdbcType=INTEGER}
  AND task_status = 'PENDING'
  AND (delete_flag = 0 OR delete_flag IS NULL)
